'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import './live-log-stream.css';

export interface LogEntry {
  id: number;
  time: string;
  level: 'info' | 'warn' | 'error';
  text: string;
}

export interface LiveLogStreamProps {
  entries: LogEntry[];
  label: string;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * New entries slide in at the bottom. While you are at the bottom the view
 * follows them; scroll up to read and it stays exactly where you are, with a
 * "Jump to latest" button counting what arrived. Nothing is announced unless
 * you ask for it, so screen readers are not flooded.
 */
export function LiveLogStream({
  entries,
  label,
  className = '',
}: LiveLogStreamProps) {
  const box = useRef<HTMLOListElement>(null);
  const [following, setFollowing] = useState(true);
  const [unseen, setUnseen] = useState(0);
  const [announce, setAnnounce] = useState(false);
  const seen = useRef(entries.length);

  useIsomorphicLayoutEffect(() => {
    const el = box.current;
    if (!el) return;
    const added = entries.length - seen.current;
    seen.current = entries.length;
    if (following) el.scrollTop = el.scrollHeight;
    else if (added > 0) setUnseen((n) => n + added);
  }, [entries]);

  const latest = entries[entries.length - 1];
  return (
    <div className={`mg-log ${className}`}>
      <ol
        ref={box}
        className='mg-log__list'
        tabIndex={0}
        aria-label={label}
        onScroll={(event) => {
          const el = event.currentTarget;
          const atBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 8;
          setFollowing(atBottom);
          if (atBottom) setUnseen(0);
        }}
      >
        {entries.map((e) => (
          <li key={e.id} className='mg-log__row' data-level={e.level}>
            <time>{e.time}</time>
            <span className='mg-log__level'>{e.level.toUpperCase()}</span>
            <span>{e.text}</span>
          </li>
        ))}
      </ol>
      {!following ? (
        <button
          type='button'
          className='mg-log__jump'
          onClick={() => {
            const el = box.current!;
            el.scrollTop = el.scrollHeight;
            setFollowing(true);
            setUnseen(0);
          }}
        >
          ↓ Jump to latest{unseen ? ` (${unseen} new)` : ''}
        </button>
      ) : null}
      <label className='mg-log__announce'>
        <input
          type='checkbox'
          checked={announce}
          onChange={(event) => setAnnounce(event.target.checked)}
        />
        Announce new entries
      </label>
      <span className='mg-log__sr' aria-live='polite'>
        {announce && latest ? `${latest.level}: ${latest.text}` : ''}
      </span>
    </div>
  );
}

.mg-log {
  position: relative;
  display: grid;
  gap: 8px;
  color: var(--mg-text, #ffffff);
}

.mg-log__list {
  height: 190px;
  margin: 0;
  padding: 6px 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 12px;
  background: var(--mg-raised, #262626);
  color: #e8e8e8;
  font:
    12px/1.5 ui-monospace,
    SFMono-Regular,
    Menlo,
    monospace;
  list-style: none;
  /* Keeps the reading position steady as rows are added below it. */
  overflow-anchor: auto;
}

.mg-log__list:focus-visible {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

.mg-log__row {
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: 8px;
  padding: 2px 12px;
  animation: mg-log-in 240ms ease-out;
}

.mg-log__row time {
  color: #8f8f8f;
}

.mg-log__level {
  min-width: 42px;
  font-weight: 700;
}

.mg-log__row[data-level='info'] .mg-log__level {
  color: #ffffff;
}

.mg-log__row[data-level='warn'] .mg-log__level {
  color: #d6d6d6;
}

.mg-log__row[data-level='error'] .mg-log__level {
  color: #ffffff;
}

.mg-log__jump {
  position: absolute;
  top: 146px;
  left: 50%;
  min-height: 36px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: var(--mg-accent, #eaf2fb);
  color: #080808;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  box-shadow: 0 8px 18px -8px rgba(0, 0, 0, 0.6);
  transform: translateX(-50%);
  cursor: pointer;
  animation: mg-log-in 200ms ease-out;
}

.mg-log__jump:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.mg-log__announce {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 36px;
  color: #b8b8b8;
  font-size: 13px;
}

.mg-log__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

@keyframes mg-log-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}

.mg-log__jump {
  animation-name: mg-log-jump;
}

@keyframes mg-log-jump {
  from {
    opacity: 0;
    transform: translate(-50%, 6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-log__row,
  .mg-log__jump {
    animation: none;
  }
}
